corrected_code:
router.post('/auth/mfa/challenge/verify', async (req, res) => {
  const { mfaSessionId, totpCode } = req.body;
  const preAuthCookie = req.signedCookies['pre_auth_token'];
  if (!preAuthCookie) {
    return res.status(401).json({ error: 'Missing primary pre-authentication session' });
  }

  const sessionData = await redisClient.get(`mfa_pending:${mfaSessionId}`);
  if (!sessionData) {
    return res.status(401).json({ error: 'MFA session expired or invalid' });
  }

  const { userId, secret, cookieBindingHash } = JSON.parse(sessionData);
  const incomingHash = crypto.createHash('sha256').update(preAuthCookie).digest('hex');
  if (cookieBindingHash !== incomingHash) {
    return res.status(403).json({ error: 'MFA challenge session does not match primary auth credentials' });
  }

  const verified = speakeasy.totp.verify({
    secret,
    encoding: 'base32',
    token: totpCode
  });

  if (!verified) {
    return res.status(400).json({ error: 'Invalid verification code' });
  }

  await redisClient.del(`mfa_pending:${mfaSessionId}`);
  res.clearCookie('pre_auth_token');
  const accessToken = jwt.sign({ sub: userId }, process.env.JWT_SECRET, { expiresIn: '1h' });
  res.json({ token: accessToken });
});
